// === PHẦN 2: TYPESCRIPT AST VALIDATOR + EXPLAIN COST GATE ===
import { Parser } from 'node-sql-parser';
import type { Pool } from 'pg';

const ALLOWED_VIEWS = new Set(['ai_bi.v_exec_revenue_daily', 'ai_bi.v_ar_aging_summary', 'ai_bi.v_lead_funnel_daily']);
const BLOCKED_FN_RE = /\b(pg_sleep|pg_read_file|pg_ls_dir|dblink|lo_import|lo_export|inet_server_addr)\b/i;
const parser = new Parser();

export function validateSafeSelectAst(rawSql: string): string {
  if (BLOCKED_FN_RE.test(rawSql)) throw new Error('Blocked dangerous PostgreSQL system function');
  const ast = parser.astify(rawSql, { database: 'PostgresQL' });
  const statements = Array.isArray(ast) ? ast : [ast];
  if (statements.length !== 1 || statements[0].type !== 'select') {
    throw new Error('Only a single SELECT statement is permitted');
  }
  const stmt = statements[0] as any;
  if (Array.isArray(stmt.with)) {
    for (const cte of stmt.with) {
      if (cte?.stmt?.type && cte.stmt.type !== 'select') throw new Error('Mutating CTE is forbidden');
    }
  }
  const refs = parser.tableList(rawSql, { database: 'PostgresQL' });
  for (const ref of refs) {
    const [op, schema, table] = ref.split('::');
    const fqtn = schema && schema !== 'null' ? `${schema}.${table}` : table;
    if (op !== 'select' || !ALLOWED_VIEWS.has(fqtn)) {
      throw new Error(`Unauthorized table/operation reference: ${ref}`);
    }
  }
  if (!stmt.limit || Number(stmt.limit?.value?.[0]?.value ?? 9999) > 200) {
    stmt.limit = { seperator: '', value: [{ type: 'number', value: 200 }] };
  }
  return parser.sqlify(stmt, { database: 'PostgresQL' });
}

export async function runGuardedExecQuery(replicaPool: Pool, rawSql: string, ctx: { userRole: string; branchCode: string }) {
  const safeSql = validateSafeSelectAst(rawSql);
  const client = await replicaPool.connect();
  try {
    await client.query('BEGIN TRANSACTION READ ONLY');
    await client.query(`SET LOCAL statement_timeout = '5000ms'`);
    await client.query(`SELECT set_config('app.user_role', $1, true), set_config('app.branch_code', $2, true)`, [
      ctx.userRole,
      ctx.branchCode,
    ]);
    const explainRes = await client.query(`EXPLAIN (FORMAT JSON) ${safeSql}`);
    const totalCost = Number(explainRes.rows?.[0]?.['QUERY PLAN']?.[0]?.Plan?.['Total Cost'] ?? 0);
    if (totalCost > 25000) throw new Error(`Query cost (${totalCost}) exceeds safety threshold; narrow date range.`);
    const dataRes = await client.query(safeSql);
    await client.query('COMMIT');
    return { sql: safeSql, rows: dataRes.rows, totalCost };
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}
